SELECT 'ни один этап не разобран: шапка и перечни не сверялись' AS detail WHERE NOT EXISTS (SELECT 1 FROM project_milestone_count WHERE project_id = $1) AND EXISTS (SELECT 1 FROM project_plan_milestones WHERE project_id = $1) UNION ALL SELECT c.milestone_id || ' — шапка говорит ' || c.said || ' ' || c.what || ', перечень называет ' || c.listed FROM project_milestone_count c WHERE c.project_id = $1 AND c.said <> c.listed ORDER BY 1
